/*jslint browser: true*/
/*global $, jQuery*/
$(document).ready(function () {
	'use strict';
	$.datepicker.regional['cs'] = {
		closeText: 'Hotovo',
		prevText: 'Předchozí',
		nextText: 'Další',
		currentText: 'Dnes',
		monthNames: ['Leden', 'Únor', 'Březen', 'Duben', 'Květen', 'Červen', 'Červenec', 'Srpen', 'Září', 'Říjen', 'Listopad', 'Prosinec'],
		monthNamesShort: ['Led', 'Úno', 'Bře', 'Dub', 'Kvě', 'Čer', 'Čec', 'Srp', 'Zář', 'Říj', 'Lis', 'Pro'],
		dayNames: ['Neděle', 'Pondělí', 'Úterý', 'Středa', 'Čtvrtek', 'Pátek', 'Sobota'],
		dayNamesShort: ['Ned', 'Pon', 'Úte', 'Stř', 'Čtv', 'Pát', 'Sob'],
		dayNamesMin: ['Ne', 'Po', 'Út', 'St', 'Čt', 'Pá', 'So'],
		weekHeader: 'Tý',
		dateFormat: 'dd.mm.yy',
		firstDay: 1,
		isRTL: false,
		showMonthAfterYear: false,
		yearSuffix: ''
	};
	$.datepicker.setDefaults($.datepicker.regional['cs']);

	var makeDateInput = function (object) {
		object.dateinput({
			dateFormat: 'd.m.yy',
			datetime: {
				dateFormat: 'd.m.yy',
				timeFormat: 'H:mm:ss',
				options: {
					changeYear: true
				}
			},
			'datetime-local': {
				dateFormat: 'd.m.yy',
				timeFormat: 'H:mm:ss'
			},
			date: {
				dateFormat: 'd.m.yy'
			},
			month: {
				dateFormat: 'MM yy'
			},
			week: {
				dateFormat: "w. 'week of' yy"
			},
			time: {
				timeFormat: 'H:mm:ss'
			}
		});
	};

	var jsControls = function () {
		var todayDate = new Date();
		$(".select2").select2({width: 'resolve'});
		$(".select2-max-2").select2({maximumSelectionSize: 2, width: 'resolve'});
		$(".select2-max-1").select2({
			maximumSelectionSize: 1,
			width: 'resolve',
			formatSelectionTooBig: function (limit) {
				if (limit == 1) {
					return "Můžete zvolit jen jednu položku";
				} else if (limit <= 4) {
					return "Můžete zvolit maximálně "+smallNumbers[limit](false)+" položky";
				} else {
					return "Můžete zvolit maximálně "+limit+" položek";
				}
			},
			formatNoMatches: function () { return "Nenalezeny žádné položky"; }
		});
		makeDateInput($('input[type=date]'));

		$(".register-conditions-toggle").click(function () {
			$('.register-conditions').slideToggle();
		});

		$('.modal-close:not(.not-js)').attr('href', '').on('click', null, function (e) {
			$('.modal-bg, .form-box').fadeOut(100);
			e.preventDefault();
			return false;
		});

		$('input.datepicker').combodate({
			minYear: 1920,
			maxYear: todayDate.getFullYear(),
			smartDays: true
		});
	};

	jsControls();

	$.nette.ext('jsControls', {
		success: jsControls
	});

	/**
	 * REGISTRACE / EDITACE CIRKUS
	 */
	$(document).on('change', 'input[name="sex"]', function () {
		var value = $('input[name="sex"]:checked').val();
		$.each($('label[data-toggle="sex-dependend"] .sexspan'),function(){
			$(this).html($(this).data(value === 'Žena' ? 'woman':'man'));
		});
	});

	/* Aktivní hráč */
	$(document).on('change', 'input[name="activeplayer"]', function () {
		$.cirkusSlide($(this), "activeplayer-depended");
	});

	$(document).on('change', 'input[name="cslhmember"]', function () {
		$.cirkusSlide($(this), "cslhmember-depended");
		$.cirkusCheckboxExclusiv($(this), $('input[name="nocslhmember"]'));
	});

	$(document).on('change', 'input[name="nocslhmember"]', function () {
		$.cirkusCheckboxExclusiv($(this), $('input[name="cslhmember"]'));
	});

	/*Rodič hráče*/
	$(document).on('change', 'input[name="parentofplayer"]', function () {
		$.cirkusSlide($(this), "parentofplayer-depended");
		$('input[name="child1"]').attr('value', $(this).is(':checked') ? 1 : 0);
	});

	$(document).on('change', 'input[name^="childcslhmember"]', function () {
		var obj = $(this);
		var name = obj.attr('name');
		var index = name.substr(name.length - 1);

		$.cirkusSlide(obj, "childcslhmember" + index + "-depended");
	});

	$(document).on('change', '.cirkus-form input[name^="agreeprogram"]', function () {
		var obj = $(this);
		$('.cirkus-form input[data-toggle="agree-dependend"]').attr('value', obj.is(':checked') ? 1 : 0);
	});

	/**
	 * Otevírání/zavírání dalších dětí
	 */
	$(document).on('click', 'a.next-child', function (event) {
		event.preventDefault();
		var childIndex = $(this).data('nextchild');
		var elSlideAble = $('[data-childindex="' + childIndex + '"]');
		var elChildHidden = $('input[name="child' + childIndex + '"]');
		var isChild = parseInt(elChildHidden.val()) || 0;

		var lastNext = function () {
			var closest = $('a[data-nextchild="3"]').closest('ul');

			if ($('input[name="child2"]').val() > 0) {
				closest.show();
			} else if ($('input[name="child3"]').val() <= 0) {
				closest.hide();
			}
		};

		if (!isChild) {
			$(this).text($(this).data('remove'));
			elSlideAble.slideDown();
			elChildHidden.val(1);
		} else {
			$(this).text($(this).data('add'));
			elSlideAble.slideUp();
			$.cirkusClearing(elSlideAble);//reset vnořených inputů
			elChildHidden.val(0);
		}

		lastNext();

		return false;
	});

});

$.extend({
	cirkusSlide: function (obj, dataToggle) {
		'use strict';
		var dependent = $('[data-toggle="' + dataToggle + '"]');

		if (obj.is(':checked')) {
			dependent.slideDown();
		} else {
			dependent.slideUp();
			$.cirkusClearing(dependent);//reset vnořených inputů
		}
	},
	cirkusCheckboxExclusiv: function (activeObj, unActiveObj) {
		'use strict';
		if (activeObj.is(':checked')) {
			unActiveObj.attr('checked', false);
			unActiveObj.trigger('change');
		}
	},
	cirkusClearing: function (obj) {
		'use strict';
		$(':input', obj)
			.val('')
			.removeAttr('checked')
			.removeAttr('selected');

		$(':input', obj).trigger("change");
	}
});
